import os
from typing import List, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def list_objects(bucket: str, prefix: str = "", region_name: Optional[str] = None) -> List[Dict[str, object]]:
    """
    List objects stored in an Amazon S3 bucket under a given prefix.

    Returns a list of dictionaries with common object metadata:
    - Key
    - Size
    - LastModified
    - ETag
    - StorageClass
    """
    session = boto3.session.Session(region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))
    s3 = session.client("s3")

    results: List[Dict[str, object]] = []
    continuation_token: Optional[str] = None

    try:
        while True:
            kwargs = {"Bucket": bucket}
            if prefix:
                kwargs["Prefix"] = prefix
            if continuation_token:
                kwargs["ContinuationToken"] = continuation_token

            response = s3.list_objects_v2(**kwargs)

            for obj in response.get("Contents", []):
                results.append(
                    {
                        "Key": obj.get("Key"),
                        "Size": obj.get("Size"),
                        "LastModified": obj.get("LastModified"),
                        "ETag": obj.get("ETag"),
                        "StorageClass": obj.get("StorageClass"),
                    }
                )

            if response.get("IsTruncated"):
                continuation_token = response.get("NextContinuationToken")
            else:
                break

    except (ClientError, BotoCoreError):
        raise

    return results
